param([ValidateRange(1,5)][int]$Samples=1,[ValidateRange(1,30)][int]$IntervalSeconds=15)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
. "$PSScriptRoot/scheduled-observation-helpers.ps1"
$stage='PUBLIC_PINS';$context=$null
try {
 Import-Phase08SchedulerChildDefinitions;$pins=Get-Phase08SchedulerPins
 $stage='PROTECTED_CONTEXT';$context=Read-Phase08ProtectedJson;Assert-Phase08SchedulerContext $context $pins;$context=$null
 $observations=@()
 for($i=0;$i -lt $Samples;$i++) {
  $stage='READONLY_STATUS';$deployment=Get-Phase08ObservedDeployment $pins
  $query=@'
BEGIN READ ONLY;
SET LOCAL statement_timeout=15000;
SELECT current_database() AS database,current_user AS role,
 (SELECT count(*) FROM phase08_meta_ads.source_connections)::int AS source_count,
 (SELECT count(*) FROM daily_data_sync_ops.schedules)::int AS schedule_count,
 (SELECT count(*) FROM pg_catalog.pg_tables WHERE schemaname='phase08_meta_ads')::int AS tables,
 (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='phase08_meta_ads' AND c.relkind='r' AND c.relrowsecurity AND c.relforcerowsecurity)::int AS force_rls,
 (SELECT json_build_object('stopped',stopped,'targetId',target_id,'origin',origin) FROM daily_data_sync_ops.settings WHERE singleton) AS settings,
 (SELECT json_build_object('total',count(*),'active',count(*) FILTER(WHERE active)) FROM cron.job WHERE jobname LIKE 'daily-data-sync-08-%') AS jobs,
 (SELECT coalesce(json_agg(row_to_json(q)),'[]'::json) FROM (SELECT provider,key,paused,cadence_days AS "cadenceDays",window_minutes AS "windowMinutes",to_char(anchor_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS "anchorAt" FROM daily_data_sync_ops.schedules ORDER BY key LIMIT 3)q) AS schedules,
 (SELECT coalesce(json_agg(row_to_json(q)),'[]'::json) FROM (SELECT s.provider,to_char(a.scheduled_for AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS "scheduledFor",a.status,a.http_status AS "httpStatus",a.safe_code AS "safeCode",a.completed_units AS "completedUnits",a.total_units AS "totalUnits",a.elapsed_ms AS "elapsedMs",a.inspection_only AS "inspectionOnly" FROM daily_data_sync_ops.attempts a JOIN daily_data_sync_ops.schedules s ON s.key=a.schedule_key ORDER BY a.id DESC LIMIT 60)q) AS attempts,
 (SELECT coalesce(json_agg(row_to_json(q)),'[]'::json) FROM (SELECT c.provider,r.from_date::text AS "fromDate",r.to_date::text AS "toDate",r.status,r.safe_error_code AS "safeErrorCode",r.attempt_count AS attempts,r.rows_published AS "rowsPublished",to_char(r.started_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS "startedAt",to_char(r.finished_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS "finishedAt" FROM phase08_meta_ads.sync_runs r JOIN phase08_meta_ads.source_connections c ON c.id=r.connection_id WHERE c.id IN ('0c35defe-45fc-4a54-bc79-704df7bca5b1','b9ebee4b-5d4e-4eae-92b9-9facfbf3c900','1277dc2a-ea20-41eb-8a1c-ab1bfcc564f6') AND r.trigger='SCHEDULED' ORDER BY r.started_at DESC NULLS FIRST LIMIT 30)q) AS runs,
 (SELECT json_build_object('total',count(*),'succeeded',count(*) FILTER(WHERE u.status='SUCCEEDED'),'attempts',coalesce(sum(u.attempts),0)) FROM phase08_meta_ads.run_units u JOIN phase08_meta_ads.sync_runs r ON r.id=u.run_id WHERE r.trigger='SCHEDULED' AND r.connection_id IN ('0c35defe-45fc-4a54-bc79-704df7bca5b1','b9ebee4b-5d4e-4eae-92b9-9facfbf3c900','1277dc2a-ea20-41eb-8a1c-ab1bfcc564f6')) AS units,
 (SELECT coalesce(json_agg(row_to_json(q)),'[]'::json) FROM (SELECT c.provider,v.data_kind::text AS "dataKind",v.metric_date::text AS "metricDate",v.source::text,v.state::text,v.row_count AS "rowCount",(v.last_success_run_id IS NOT NULL) AS "hasSuccessRun",(v.reconciliation_status='CAFE24_API_ONLY_VERIFIED') AS "cafeApiOnlyVerified",EXISTS(SELECT 1 FROM phase08_meta_ads.source_policies p WHERE p.connection_id=v.connection_id AND p.data_kind=v.data_kind AND p.primary_source='API' AND p.reason='CAFE24_SCHEDULED_API_ONLY' AND p.from_date=v.metric_date AND p.to_date=v.metric_date+1) AS "cafeDayApiPolicy" FROM phase08_meta_ads.source_coverage v JOIN phase08_meta_ads.source_connections c ON c.id=v.connection_id WHERE c.id IN ('0c35defe-45fc-4a54-bc79-704df7bca5b1','b9ebee4b-5d4e-4eae-92b9-9facfbf3c900','1277dc2a-ea20-41eb-8a1c-ab1bfcc564f6') ORDER BY v.metric_date DESC,v.data_kind LIMIT 100)q) AS coverage,
 (SELECT json_build_object('total',count(*),'live',count(*) FILTER(WHERE expires_at>clock_timestamp())) FROM phase08_meta_ads.sync_leases WHERE connection_id IN ('0c35defe-45fc-4a54-bc79-704df7bca5b1','b9ebee4b-5d4e-4eae-92b9-9facfbf3c900','1277dc2a-ea20-41eb-8a1c-ab1bfcc564f6')) AS leases,
 (SELECT json_build_object('total',count(*),'expired',count(*) FILTER(WHERE x.expires_at<=clock_timestamp()),'nearestExpiry',to_char(min(x.expires_at) AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) FROM phase08_meta_ads.sync_unit_checkpoints x JOIN phase08_meta_ads.sync_runs r ON r.id=x.run_id WHERE r.connection_id='0c35defe-45fc-4a54-bc79-704df7bca5b1') AS checkpoints,
 (SELECT json_build_object('total',count(*),'active',count(*) FILTER(WHERE state='active'),'idle',count(*) FILTER(WHERE state='idle')) FROM pg_stat_activity WHERE usename='phase08_runtime') AS runtime_sessions,
 (SELECT coalesce(json_agg(row_to_json(q)),'[]'::json) FROM (SELECT c.provider,count(DISTINCT r.id) AS runs,count(u.unit_key) AS units,count(u.unit_key) FILTER(WHERE u.status='SUCCEEDED') AS "succeededUnits",coalesce(sum(u.attempts),0) AS "unitAttempts" FROM phase08_meta_ads.source_connections c LEFT JOIN phase08_meta_ads.sync_runs r ON r.connection_id=c.id AND r.trigger='SCHEDULED' LEFT JOIN phase08_meta_ads.run_units u ON u.run_id=r.id WHERE c.id IN ('0c35defe-45fc-4a54-bc79-704df7bca5b1','b9ebee4b-5d4e-4eae-92b9-9facfbf3c900','1277dc2a-ea20-41eb-8a1c-ab1bfcc564f6') GROUP BY c.provider ORDER BY c.provider)q) AS provider_counts;
COMMIT;
'@
  $rows=@(Invoke-Phase08Management -Action Query -Query $query)
  if($rows.Count -ne 1 -or $rows[0].database -cne 'postgres' -or $rows[0].role -cne 'postgres' -or $rows[0].tables -ne 68 -or $rows[0].force_rls -ne 68 -or $rows[0].source_count -ne 3 -or $rows[0].schedule_count -ne 3 -or $rows[0].settings.targetId -cne $pins.identity.targetId -or $rows[0].settings.origin -cne $pins.identity.origin){throw 'observation-identity'}
  $row=$rows[0]
  foreach($attempt in $row.attempts){if($attempt.safeCode -isnot [string] -or $attempt.safeCode -cnotin @('COMPLETE','APP_INCOMPLETE','HTTP_RETRYABLE','APP_LEASE_BUSY','HTTP_REJECTED','MACHINE_AUTH_REQUIRED','HTTP_EXCEPTION','TRANSPORT_FAILED','INVALID_APP_RESPONSE','MISSING_SCHEDULE','INCOMPLETE_SCHEDULE','OPERATOR_RETRY_APPROVED','CAFE24_REPLAY_FIXTURE_APPROVED','META_LINK_RETRY_APPROVED','UNKNOWN')){$attempt.safeCode='UNCLASSIFIED'};$kind=if($attempt.status -cin @('OPERATOR_RETRY_APPROVED','CAFE24_REPLAY_FIXTURE_APPROVED','META_LINK_RETRY_APPROVED')){'OPERATOR_CONTROL_MARKER'}else{'SCHEDULER_CALL'};if($attempt -is [Collections.IDictionary]){$attempt['attemptKind']=$kind}else{$attempt|Add-Member -NotePropertyName attemptKind -NotePropertyValue $kind -Force}}
  foreach($run in $row.runs){if($null -ne $run.safeErrorCode -and ($run.safeErrorCode -isnot [string] -or $run.safeErrorCode -cnotin @('SOURCE_SELECTION_REQUIRED','ACCOUNT_SCOPE_MISMATCH','CURRENCY_MISMATCH','TIMEZONE_MISMATCH','FIELD_UNSUPPORTED','ATTRIBUTION_MISMATCH','PARTIAL_PAGE','RECONCILIATION_FAILED','LEASE_LOST','RUN_LIMIT_EXCEEDED','PROVIDER_AUTH_REQUIRED','PROVIDER_RATE_LIMITED','PROVIDER_UNAVAILABLE','PROVIDER_VERSION_UNVERIFIED'))){$run.safeErrorCode='UNCLASSIFIED'}}
  $observations+=@{observedAt=[DateTimeOffset]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ss.fffZ');deployment=$deployment;sourceConnectionsCount=$row.source_count;scheduleTotalCount=$row.schedule_count;settings=@{stopped=$row.settings.stopped};jobs=$row.jobs;schedules=$row.schedules;attempts=$row.attempts;runs=$row.runs;units=$row.units;coverage=$row.coverage;leases=$row.leases;checkpoints=$row.checkpoints;runtimeSessionCounts=$row.runtime_sessions;runtimeSessionSemantics='Supavisor backend sessions; frontend pool idle/disconnect is not inferred';providerCounts=$row.provider_counts;historyLimits=@{attempts=60;runs=30;coverage=100};earlierHistoryNotScanned=(@($row.attempts).Count -ge 60 -or @($row.runs).Count -ge 30 -or @($row.coverage).Count -ge 100)}
  if($i -lt $Samples-1){Start-Sleep -Seconds $IntervalSeconds}
 }
 @{state='PHASE08_SCHEDULER_OBSERVED';observations=$observations;readOnly=$true;applicationHttpRequests=0;providerRequests=0;onTimeCompletionInferred=$false;rssMeasured=$false;costMeasured=$false;rawSecretsReturned=0}|ConvertTo-Json -Depth 15 -Compress
}catch{@{state='PHASE08_SCHEDULER_OBSERVATION_FAILED';stage=$stage;rawErrorSuppressed=$true;retryPerformed=$false}|ConvertTo-Json -Compress;exit 1}
finally{$context=$null;$rows=$null;$row=$null;$observations=$null}
